SourceCode.Declaration:
/// <summary>
/// MET journal unit conversion
/// </summary>
internal class METJournalUnitConversion
{
    InventTableModule inventTableModule;
}

Method.Source:
/// <summary>
/// Get converted Qty CWQty for Item
/// </summary>
/// <param name = "_inventLocation">InventLocation</param>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_journalQty">Journal qty</param>
/// <param name = "_isCWQty">boolean</param>
/// <returns>Quantity</returns>
public Qty getConvertedQtyCWQtyForItem(InventLocation _inventLocation, ItemId _itemId, Qty _journalQty, NoYes _isCWQty = NoYes::No)
{
    Qty                 journalCOnvertedQty = _journalQty;
    InventDim           tempInventDim;
    UnitOfMeasureSymbol wareHouseUnit;
    UnitOfMeasureSymbol cWUnit;
    UnitOfMeasureSymbol inventoryUnit;
    METInventLocation   metInventLocation;

    metInventLocation = METInventLocation::findByInventLocationId(_inventLocation.InventLocationId);
    tempInventDim.InventLocationId = _inventLocation.InventLocationId;
    tempInventDim.InventSiteId     = _inventLocation.InventSiteId;
    wareHouseUnit = METInventLocation::getWarehouseUnit(_itemId, tempInventDim);
    inventoryUnit = this.getInventoryUnit(_itemId);

    if (_isCWQty == NoYes::Yes && metInventLocation.ExternalWMSUnit == METExtWMSUnit::DefaultInventoryUnit)
    {
        cWUnit = PdsCatchWeightItem::find(_itemId).PdsCWUnitId;
        if (cWUnit && (cWUnit != inventoryUnit))
        {
            journalCOnvertedQty = this.getConvertedQty(_itemId,
                                                    tempInventDim.inventDimId,
                                                    cWUnit,
                                                    inventoryUnit,
                                                    NoYes::Yes,
                                                    _journalQty);
        }
    }

    if ((metInventLocation.ExternalWMSUnit == METExtWMSUnit::DefaultPurchaseUnit) ||
        (metInventLocation.ExternalWMSUnit == METExtWMSUnit::DefaultSellUnit))
    {
        if (wareHouseUnit && (wareHouseUnit != this.getInventoryUnit(_itemId)))
        {
            journalCOnvertedQty = this.getConvertedQty(_itemId,
                                                    tempInventDim.inventDimId,
                                                    wareHouseUnit,
                                                    inventoryUnit,
                                                    NoYes::Yes,
                                                    _journalQty);
        }
    }

    return journalCOnvertedQty;
}

/// <summary>
/// Get converted CWQty for Item
/// </summary>
/// <param name = "_inventLocation">InventLocation</param>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_journalQty">Journal qty</param>
/// <returns>Quantity</returns>
public Qty getConvertedCWQtyForItem(InventLocation _inventLocation, ItemId _itemId, Qty _journalQty)
{
    Qty                 journalCOnvertedQty = _journalQty;
    InventDim           tempInventDim;
    UnitOfMeasureSymbol wareHouseUnit;
    UnitOfMeasureSymbol cWUnit;
    METInventLocation   metInventLocation;

    metInventLocation = METInventLocation::findByInventLocationId(_inventLocation.InventLocationId);
    tempInventDim.InventLocationId = _inventLocation.InventLocationId;
    tempInventDim.InventSiteId     = _inventLocation.InventSiteId;
    wareHouseUnit = METInventLocation::getWarehouseUnit(_itemId, tempInventDim);

    if ((metInventLocation.ExternalWMSUnit == METExtWMSUnit::DefaultPurchaseUnit) ||
        (metInventLocation.ExternalWMSUnit == METExtWMSUnit::DefaultSellUnit))
    {
        cWUnit = PdsCatchWeightItem::find(_itemId).PdsCWUnitId;
        if (wareHouseUnit && (wareHouseUnit != cWUnit))
        {
            journalCOnvertedQty = this.getConvertedQty(_itemId,
                                                    tempInventDim.inventDimId,
                                                    wareHouseUnit,
                                                    cWUnit,
                                                    NoYes::Yes,
                                                    _journalQty);
        }
    }

    return journalCOnvertedQty;
}

/// <summary>
/// Get converted qty
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_inventDimId">InventDimId</param>
/// <param name = "_fromUnit">UnitOfMeasureSymbol</param>
/// <param name = "_toUnit">UnitOfMeasureSymbol</param>
/// <param name = "_roundUpValue">boolean</param>
/// <param name = "_journalQty">Qty</param>
/// <returns>Qty</returns>
public Qty getConvertedQty(ItemId _itemId, InventDimId _inventDimId, UnitOfMeasureSymbol _fromUnit, UnitOfMeasureSymbol _toUnit, boolean _roundUpValue, Qty _journalQty)
{
    EcoResProductUnitConverter productUnitConverter = EcoResProductUnitConverter::newGivenUnitSymbolsForReleasedProduct(_itemId,
                                                                                                                        _inventDimId,
                                                                                                                        _fromUnit,
                                                                                                                        _toUnit,
                                                                                                                        _roundUpValue);

    return productUnitConverter.convertValue(_journalQty);
}

/// <summary>
/// Get inventory unit
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <returns>UnitOfMeasureSymbol</returns>
public UnitOfMeasureSymbol getInventoryUnit(ItemId _itemId)
{
    UnitOfMeasureSymbol inventUnit;
    select firstonly UnitId from inventTableModule
        where inventTableModule.ItemId  == _itemId
        && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;

    if (inventTableModule.UnitId)
    {
        inventUnit = inventTableModule.UnitId;
    }

    return inventUnit;
}

/// <summary>
/// Constructs and returns <c>METJournalUnitConversion</c> object.
/// </summary>
/// <returns> <c>METJournalUnitConversion</c> object. </returns>
public static METJournalUnitConversion construct()
{
    METJournalUnitConversion journalUnitConversion = new METJournalUnitConversion();

    return journalUnitConversion;
}
